const d = $input.item.json;
const e = d.enriched || {};
const asOf = String(d.asOf || '').includes('T') ? String(d.asOf).split('T')[1].slice(0,5) : '15:00';
const market = e.market?.total || 'NA';
const etfD = e.etf?.total || 'NA';
const etfM = etfD !== 'NA' ? 'OK' : 'NA';
const share = (market !== 'NA' && etfD !== 'NA' && market > 0) ? ((etfD / market) * 100).toFixed(2) : 'NA';
let failStep = 'None'; let err = 'None';
if (e.journal?.steps) {
  const failed = e.journal.steps.find(s => s.status === 'failed');
  if (failed) { failStep = failed.name; err = failed.error?.message || (failed.warnings || []).find(w => w.severity === 'error')?.message || 'failed'; }
}
const line1 = `M0-A ❌ day=${d.day} asOf=${asOf}`;
const line2 = `market=${market} etfD=${etfD} etfM=${etfM} share=${share === 'NA' ? 'NA' : share + '%'}`;
const line3 = `out: amounts.json + etf_minute + etf_daily (failStep=${failStep} err=${err})`;
return [{ summary: `${line1}\n${line2}\n${line3}` }];

const d = $input.item.json;
const e = d.enriched || {};
const icon = d.status === 'partial' ? '⚠️' : '✅';
const asOf = String(d.asOf || '').includes('T') ? String(d.asOf).split('T')[1].slice(0,5) : '15:00';
const market = e.market?.total || 'NA';
const etfD = e.etf?.total || 'NA';
const etfM = etfD !== 'NA' ? 'OK' : 'NA';
const share = (market !== 'NA' && etfD !== 'NA' && market > 0) ? ((etfD / market) * 100).toFixed(2) : 'NA';
const line1 = `M0-A ${icon} day=${d.day} asOf=${asOf}`;
const line2 = `market=${market} etfD=${etfD} etfM=${etfM} share=${share === 'NA' ? 'NA' : share + '%'}`;
const line3 = `out: amounts.json + etf_minute + etf_daily`;
return [{ summary: `${line1}\n${line2}\n${line3}` }];
